"""Generate a disposable test baseline from a metadata export, never customer rows.
Usage: python scripts/build-backend-fixture.py /path/to/schema.json > /tmp/baseline.sql
Missing function bodies/triggers are deliberately NOT represented as verified.
"""
import json, sys
s = json.load(open(sys.argv[1]))
def q(value): return '"' + value.replace('"', '""') + '"'
print("DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='anon') THEN CREATE ROLE anon; CREATE ROLE authenticated; CREATE ROLE service_role BYPASSRLS; END IF; END $$; CREATE SCHEMA auth; CREATE SCHEMA storage;")
print("CREATE TABLE public.auction_test_marker(disposable bool DEFAULT true); INSERT INTO public.auction_test_marker VALUES(true);")
print("CREATE TABLE auth.users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text,raw_app_meta_data jsonb DEFAULT '{}',created_at timestamptz DEFAULT now());")
print("CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.jwt.claim.sub',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'sub')::uuid $$;")
print("CREATE FUNCTION auth.role() RETURNS text LANGUAGE sql STABLE AS $$ SELECT coalesce(nullif(current_setting('request.jwt.claim.role',true),''),nullif(current_setting('request.jwt.claims',true),'')::jsonb->>'role',current_user) $$;")
print("CREATE TABLE storage.buckets(id text PRIMARY KEY,name text,public bool,file_size_limit bigint,allowed_mime_types text[]);")
print("CREATE TABLE storage.objects(id uuid DEFAULT gen_random_uuid() PRIMARY KEY,bucket_id text,name text,owner_id text);")
print("CREATE FUNCTION storage.foldername(text) RETURNS text[] LANGUAGE sql IMMUTABLE AS $$ SELECT string_to_array($1,'/') $$;")
for table in sorted({r['object_name'] for r in s if r['kind']=='column'}):
    fields = []
    for r in s:
        if r['kind']!='column' or r['object_name']!=table: continue
        c = r['details']; name=c['name']; typ=c['type']; default=c.get('default')
        if typ.startswith('_'): typ=typ[1:]+'[]'
        if default=='<redacted default>': default="'{}'::jsonb" if name in ['inspection','specifications','payload'] else "'[]'::jsonb" if typ=='jsonb' else None
        if name=='id' and typ in ['int8','int4']:
            fields.append(q(name)+' '+typ+' GENERATED BY DEFAULT AS IDENTITY'); continue
        fields.append(q(name)+' '+typ+(' NOT NULL' if c['nullable']=='NO' else '')+(' DEFAULT '+default if default else ''))
    print('CREATE TABLE public.'+q(table)+'('+','.join(fields)+');')
for r in sorted(s,key=lambda r: r.get('details',{}).get('definition','').startswith('FOREIGN KEY')):
    if r['kind']=='constraint': print('ALTER TABLE public.'+q(r['object_name'])+' ADD CONSTRAINT '+q(r['details']['name'])+' '+r['details']['definition']+';')
print("CREATE SEQUENCE public.fixture_dealer_sequence; CREATE FUNCTION public.generate_dealer_id() RETURNS text LANGUAGE sql AS $$ SELECT 'DLR-'||lpad(nextval('public.fixture_dealer_sequence')::text,6,'0') $$;")
print("GRANT USAGE ON SCHEMA public,auth,storage TO anon,authenticated,service_role; GRANT ALL ON ALL TABLES IN SCHEMA public,auth,storage TO service_role; GRANT USAGE ON ALL SEQUENCES IN SCHEMA public TO service_role;")
for r in s:
    if r['kind']=='bucket':print("INSERT INTO storage.buckets(id,name,public) VALUES ('"+r['object_name']+"','"+r['object_name']+"',true);")

for r in s:
    if r['kind']=='rls' and r['details'].get('enabled'):print('ALTER TABLE public.'+q(r['object_name'].removeprefix('public.'))+' ENABLE ROW LEVEL SECURITY;')
print("ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public,storage TO anon,authenticated;")
